import React, { useState, useEffect } from 'react';
import './RiverDashboard.css';

// ==========================================
// CONFIGURATION (DO NOT CHANGE)
// ==========================================
const DATA_BASE_URL = '.';
const CSV_FILE_NAME = 'forecast_outputs.csv';
const TXT_FILE_NAME = 'lime_short_sentences.txt';

// Alert Thresholds
const ALERT_THRESHOLDS = {
    NORMAL: 3.0,
    WATCH: 4.0,
    WARNING: 5.0
};

const RiverDashboard = () => {
    // --- State ---
    const [currentLevel, setCurrentLevel] = useState(0);
    const [forecastData, setForecastData] = useState([]); // Array for 6-hour forecast
    const [limeDetails, setLimeDetails] = useState([]);
    const [lastUpdated, setLastUpdated] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);

    // --- Helpers ---
    const getAlertLevel = (level) => {
        if (level < ALERT_THRESHOLDS.NORMAL) return 'normal';
        if (level < ALERT_THRESHOLDS.WATCH) return 'watch';
        if (level < ALERT_THRESHOLDS.WARNING) return 'warning';
        return 'critical';
    };

    const getAlertMessage = (level, value) => {
        const valStr = value.toFixed(2);
        switch (level) {
            case 'normal': return `🟢 Water level ${valStr}m - River levels are currently normal. Continue regular activities.`;
            case 'watch': return `🟡 Water level ${valStr}m - ⚠️ WATCH ALERT: River levels are elevated. Avoid low-lying areas.`;
            case 'warning': return `🟠 Water level ${valStr}m - 🚨 WARNING: Flooding is likely! Move to higher ground.`;
            case 'critical': return `🔴 Water level ${valStr}m - 🆘 CRITICAL FLOOD ALERT: Immediate evacuation may be required!`;
            default: return `Water level ${valStr}m`;
        }
    };

    // --- Data Fetching Logic ---
    const fetchData = async () => {
        setIsLoading(true);
        setError(null);
        try {
            // 1. Fetch Forecast CSV
            const csvResponse = await fetch(`${DATA_BASE_URL}/${CSV_FILE_NAME}`);
            if (!csvResponse.ok) throw new Error(`Failed to load ${CSV_FILE_NAME}`);
            const csvText = await csvResponse.text();
            
            // CSV Parsing Logic
            const lines = csvText.split('\n').filter(line => line.trim() !== '');
            if (lines.length > 1) {
                // Assuming standard CSV with headers on row 0, data on row 1
                const headers = lines[0].split(',');
                const firstRowValues = lines[1].split(',');
                
                // We assume the first numeric column is current level, and subsequent are forecast
                // Or if there are multiple rows, we map them.
                // Let's treat the data as: first numeric value found = Current Level
                // Next 6 numeric values found = Forecast
                
                let numericValues = [];
                // Collect all numeric values from the first data row
                firstRowValues.forEach(val => {
                    const num = parseFloat(val.trim());
                    if (!isNaN(num)) numericValues.push(num);
                });

                if (numericValues.length > 0) {
                    setCurrentLevel(numericValues[0]); // First number is current level
                    setForecastData(numericValues.slice(1, 7)); // Next 6 are forecast
                }
            }

            // 2. Fetch LIME Text
            const txtResponse = await fetch(`${DATA_BASE_URL}/${TXT_FILE_NAME}`);
            if (!txtResponse.ok) throw new Error(`Failed to load ${TXT_FILE_NAME}`);
            const txtText = await txtResponse.text();
            setLimeDetails(txtText.split('\n').filter(line => line.trim() !== ''));

            setLastUpdated(new Date());

        } catch (err) {
            console.error("Fetch Error:", err);
            setError("Unable to retrieve data. Please ensure the files exist in the public directory.");
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        const interval = setInterval(fetchData, 30000); // Auto-refresh every 30s
        return () => clearInterval(interval);
    }, []);

    // --- Render Preparation ---
    const alertLevel = getAlertLevel(currentLevel);
    const alertMessage = getAlertMessage(alertLevel, currentLevel);
    const nextHourForecast = forecastData.length > 0 ? forecastData[0] : '--';

    if (isLoading && !lastUpdated) {
        return (
            <div className="dashboard-wrapper">
                <div className="loading-container">
                    <div className="spinner"></div>
                    <h2>Loading Kalady Periyar Tracker...</h2>
                </div>
            </div>
        );
    }

    if (error && !lastUpdated) {
        return (
            <div className="dashboard-wrapper">
                <div className="error-message">
                    <h3>⚠️ Error</h3>
                    <p>{error}</p>
                    <button className="refresh-btn" style={{position:'static', margin:'20px auto', borderRadius:'10px', width:'auto', padding:'0 20px', height:'40px', fontSize:'1rem'}} onClick={fetchData}>Retry</button>
                </div>
            </div>
        );
    }

    return (
        <div className="dashboard-wrapper">
            
            {/* Auto Refresh Indicator */}
            <div className="auto-refresh-indicator">
                <span className="status-dot" style={{marginRight: '8px'}}></span>
                <span>Auto-refresh active</span>
            </div>

            <div className="dashboard-container">
                
                {/* Header */}
                <header className="header">
                    <h1>🌊 Kalady Periyar River Water Level</h1>
                    <p>Real-time monitoring with 6-hour AI forecast</p>
                </header>

                {/* Safety Notice */}
                <div className="safety-notice">
                    <h3>⚠️ FLOOD ALERT SYSTEM ⚠️</h3>
                    <p>This is an automated river level monitoring system for public safety. Water levels can rise rapidly during heavy rainfall. Stay alert, follow evacuation orders, and keep emergency contacts ready.</p>
                </div>

                {/* Alert Banner */}
                <div className={`alert-banner ${alertLevel}`}>
                    <div>{alertMessage}</div>
                </div>

                {/* Status Bar */}
                <div className="status-bar">
                    <div className="status-indicator">
                        <div className={`status-dot ${['warning', 'critical'].includes(alertLevel) ? 'alert' : ''}`}></div>
                        <span>System Active</span>
                    </div>
                    <div className="last-update">
                        Last updated: {lastUpdated ? lastUpdated.toLocaleTimeString() : '...'}
                    </div>
                </div>

                {/* Metrics Grid */}
                <div className="metrics-grid">
                    
                    {/* Water Level Card */}
                    <div className={`metric-card alert-${alertLevel}`}>
                        <div className="metric-header">
                            <div className="metric-title">Current Water Level</div>
                            <div className="metric-icon">💧</div>
                        </div>
                        <div className="metric-value">
                            {currentLevel.toFixed(2)}
                            <span className="metric-unit">mtrs</span>
                        </div>
                        <div className="metric-timestamp">
                            Live Reading
                        </div>
                    </div>

                    {/* Next Hour Forecast Card */}
                    <div className="metric-card forecast">
                        <div className="metric-header">
                            <div className="metric-title">Next Hour Forecast</div>
                            <div className="metric-icon">🔮</div>
                        </div>
                        <div className="metric-value">
                            {typeof nextHourForecast === 'number' ? nextHourForecast.toFixed(2) : nextHourForecast}
                            <span className="metric-unit">mtrs</span>
                        </div>
                        <div className="metric-timestamp">
                            AI Prediction
                        </div>
                    </div>

                </div>

                {/* 6-Hour Forecast Section */}
                <div className="forecast-section">
                    <div className="forecast-header">
                        <div className="forecast-title">📊 6-Hour Water Level Forecast</div>
                    </div>
                    <div className="forecast-values">
                        {forecastData.map((val, index) => (
                            <div key={index} className="forecast-item">
                                <div className="forecast-time">+{index + 1}hr</div>
                                <div className="forecast-value">
                                    {typeof val === 'number' ? val.toFixed(2) : '--'} m
                                </div>
                            </div>
                        ))}
                        {forecastData.length === 0 && <p style={{color:'#7f8c8d'}}>Waiting for data...</p>}
                    </div>
                </div>

                {/* LIME Analysis (AI Causality) Section */}
                <div className="forecast-section" style={{ borderLeft: '6px solid #a29bfe' }}>
                    <div className="forecast-header">
                        <div className="forecast-title">🧠 AI Causality Analysis</div>
                    </div>
                    <div className="lime-list">
                        {limeDetails.map((line, index) => {
                            // Simple logic to detect sentiment in text for icons
                            let icon = 'ℹ️';
                            if (line.toLowerCase().includes('safe') || line.includes('[GREEN]')) icon = '✅';
                            if (line.toLowerCase().includes('risk') || line.includes('[ORANGE]')) icon = '⚠️';
                            
                            const cleanLine = line.replace(/\[GREEN\]|\[ORANGE\]/gi, '').trim();

                            return (
                                <div key={index} className="lime-item">
                                    <div className="lime-icon">{icon}</div>
                                    <div style={{fontWeight: 500}}>{cleanLine}</div>
                                </div>
                            );
                        })}
                        {limeDetails.length === 0 && <p style={{color:'#7f8c8d'}}>No analysis data available.</p>}
                    </div>
                </div>

                {/* Footer / Emergency Contacts */}
                <div style={{ marginTop: '30px', background: 'white', borderRadius: '15px', padding: '25px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }}>
                    <div style={{ padding: '15px', background: '#fff3cd', borderRadius: '10px', color: '#856404', textAlign: 'center', fontSize: '0.9em' }}>
                        <strong>DISCLAIMER:</strong> This system provides general flood risk information. 
                        Always follow official evacuation orders from local authorities. 
                        In emergency, call 100 (Police) or 101 (Fire & Rescue).
                    </div>
                </div>

            </div>

            {/* Floating Refresh Button */}
            <button className="refresh-btn" onClick={fetchData} title="Refresh Data">
                🔄
            </button>
        </div>
    );
};

export default RiverDashboard;
